<script setup>
import { ref, computed } from 'vue'
import { useRouter } from 'vue-router'
import { useEvents } from '@/composables/useEvents'
import AppModal from '@/components/ui/AppModal.vue'
const router = useRouter()
const { userRegistrations, getEventById, cancelRegistration } = useEvents()
const registrations = computed(() => userRegistrations.value.map(r => ({ ...r, event: getEventById(r.eventId) })).filter(r => r.event))
const isEventDone = id => Boolean(getEventById(id)?.done)
const isCancelModalOpen = ref(false)
const selectedRegistration = ref(null)
function handleOpenCancelModal(record) { selectedRegistration.value = record; isCancelModalOpen.value = true }
function handleConfirmCancel() { if (selectedRegistration.value) cancelRegistration(selectedRegistration.value.eventId); isCancelModalOpen.value = false; selectedRegistration.value = null }
</script>
<template><div class="your-events-container"><header class="page-header"><h1>Your Events</h1><p>Review your confirmed registrations and view official digital passes.</p></header><div v-if="!registrations.length" class="empty-state"><span class="empty-icon">🎟️</span><h2>No Registered Events Yet</h2><p>You have not signed up for any active events. Explore our catalog to find workshops, seminars, and conferences that match your interests.</p><button class="btn-primary" @click="router.push('/browse/events')">Explore Events →</button></div><div v-else class="tickets-grid"><article v-for="item in registrations" :key="item.id" class="ticket-summary-card"><div class="top-row"><span class="category-tag">{{ item.event.cat }}</span><span :class="['lifecycle-tag', isEventDone(item.eventId) ? 'tag-concluded' : 'tag-upcoming']">{{ isEventDone(item.eventId) ? 'CONCLUDED' : 'UPCOMING' }}</span><span class="booking-tag">#{{ item.bookingCode }}</span></div><h2>{{ item.event.title }}</h2><div class="card-event-title">{{ item.event.date }}</div><div class="meta-row"><strong>Location:</strong> {{ item.event.loc.replace(/^📍\s*/, '') }}</div><div class="meta-row"><strong>Attendee:</strong> {{ item.fullName }}</div><div class="card-bottom"><button class="btn-view-ticket" @click="router.push(`/browse/your-events/${item.eventId}`)">View Ticket Details →</button><button v-if="!isEventDone(item.eventId)" class="btn-subtle-cancel" @click="handleOpenCancelModal(item)">Cancel</button><span v-else class="archived-label">Archived Record</span></div></article></div><AppModal :is-open="isCancelModalOpen" title="Cancel Registration?" message="Are you sure you want to cancel your registration for this event? Your ticket will be removed and your seat will be returned to the available quota." confirm-text="Yes, Cancel Registration" @close="isCancelModalOpen=false" @confirm="handleConfirmCancel"/></div></template>
<style scoped>.your-events-container{padding:32px 0;max-width:1100px;margin:auto}.page-header{margin-bottom:32px}.page-header h1{font-size:2rem;margin-bottom:8px}.page-header p{color:var(--text-muted)}.tickets-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:24px}.ticket-summary-card,.empty-state{background:#fff;border:1px solid var(--border-color);border-radius:12px;padding:24px;box-shadow:0 4px 12px rgba(0,0,0,.04)}.empty-state{text-align:center;padding:60px 30px}.empty-state p{color:var(--text-muted);max-width:520px;margin:16px auto 24px}.empty-icon{font-size:2.5rem}.top-row,.card-bottom{display:flex;justify-content:flex-start;align-items:center;gap:9px}.top-row .booking-tag{margin-left:auto} .card-bottom{justify-content:space-between}.category-tag{background:#eee9ff;color:var(--primary);font-size:.75rem;font-weight:700;padding:5px 9px;border-radius:6px;text-transform:uppercase}.lifecycle-tag{font-size:.73rem;font-weight:700;border-radius:6px;padding:6px 10px}.tag-upcoming{background:#dbeafe;color:#1d4ed8}.tag-concluded{background:#f1f5f9;color:#64748b}.ticket-summary-card h2{font-size:1.13rem;margin:20px 0 12px;line-height:1.4}.booking-tag{font-family:monospace;color:#555;font-size:.75rem}.card-event-title,.meta-row{font-size:.88rem;color:var(--text-muted);margin:12px 0}.card-bottom{border-top:1px solid var(--border-color);padding-top:18px;margin-top:24px;flex-wrap:wrap}.btn-view-ticket,.btn-subtle-cancel{background:none;border:0;cursor:pointer;font-weight:700;font-size:.85rem;padding:0}.btn-view-ticket{color:var(--primary)}.btn-subtle-cancel{color:#94a3b8;font-weight:400}.archived-label{color:var(--text-muted);font-size:.8rem}.btn-primary{background:var(--primary);color:white;border:0;border-radius:8px;padding:12px 18px;cursor:pointer;font-weight:700}</style>
